<script setup lang="ts">
import {computed,ref} from 'vue'
import {course,type Question} from './data'
import LearningStudio from './LearningStudio.vue'
type Result={correct:boolean;attempts:number}
type Progress={stars:number;results:Record<string,Result>}
const key='lingualand-progress-v1'
function load():Progress{try{const raw=localStorage.getItem(key)||localStorage.getItem('wordquest-progress-v1');if(raw){const p=JSON.parse(raw);return {stars:Number(p.stars)||0,results:p.results||{}}}}catch{}return {stars:0,results:{}}}
const progress=ref<Progress>(load())
const page=ref<'home'|'cards'|'quiz'|'studio'>('home')
const review=ref(false),cardIndex=ref(0),flipped=ref(false),index=ref(0),selected=ref(''),tokens=ref<number[]>([]),checked=ref(false),correct=ref(false)
const questions=computed(()=>review.value?course.questions.filter(q=>!progress.value.results[q.id]?.correct):course.questions)
const q=computed<Question|undefined>(()=>questions.value[index.value])
const answer=computed(()=>q.value?.kind==='order'?tokens.value.map(i=>q.value!.tokens![i]).join(' '):selected.value)
const mastered=computed(()=>course.questions.filter(q=>progress.value.results[q.id]?.correct).length)
const wrong=computed(()=>course.questions.filter(q=>progress.value.results[q.id]&&!progress.value.results[q.id].correct).length)
const percent=computed(()=>Math.round(mastered.value/course.questions.length*100))
function save(){localStorage.setItem(key,JSON.stringify(progress.value))}
function speak(s:string){if(!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(s);u.lang='en-US';u.rate=.82;window.speechSynthesis.speak(u)}
function start(isReview=false){review.value=isReview;index.value=0;reset();page.value='quiz'}
function reset(){selected.value='';tokens.value=[];checked.value=false;correct.value=false}
function submit(){if(!q.value||!answer.value.trim()||checked.value)return;correct.value=answer.value.trim().toLowerCase()===q.value.answer.trim().toLowerCase();checked.value=true;const old=progress.value.results[q.value.id];progress.value.results[q.value.id]={correct:correct.value,attempts:(old?.attempts||0)+1};if(correct.value)progress.value.stars+=10;save()}
function next(){if(index.value+1>=questions.value.length){page.value='home';return}index.value++;reset()}
function clear(){if(confirm('确定清空本设备的学习记录吗？')){progress.value={stars:0,results:{}};save();page.value='home'}}
</script>
<template>
<div class="shell">
<aside class="sidebar"><button class="logo" @click="page='home'"><span class="logo-icon">✦</span><span>Lingua<span class="accent">Land</span><small>语言奇遇岛</small></span></button><p class="side-label">探索地图</p><button class="nav" :class="{active:page==='home'}" @click="page='home'">⌂　探险首页</button><button class="nav" :class="{active:page==='cards'}" @click="page='cards'">▤　单词森林</button><button class="nav" :class="{active:page==='studio'}" @click="page='studio'">✿　语言探索工坊</button><button class="nav" :class="{active:page==='quiz'&&!review}" @click="start()">✦　闯关练习</button><button class="nav" :class="{active:page==='quiz'&&review}" @click="start(true)">↻　错题回顾 <b>{{wrong}}</b></button><div class="sidebar-foot"><span>🦊</span><strong>每一次尝试，<br>都让你更棒一点！</strong><small>Keep going, explorer!</small></div></aside>
<main class="main"><header class="top"><span>探索世界 <span class="muted">/ {{page==='home'?'探险首页':page==='cards'?'单词森林':page==='studio'?'语言探索工坊':review?'错题回顾':'闯关练习'}}</span></span><div class="top-right"><span class="pill">{{course.grade}}年级 · {{course.term}}</span><span class="pill stars">★ {{progress.stars}}</span><button class="reset" title="清空学习记录" @click="clear">⚙</button></div></header>
<template v-if="page==='home'"><section class="hero"><div class="hero-copy"><div class="eyebrow">✦ WELCOME TO LINGUALAND</div><h1>每一次开口，<br><em>都是一场新冒险。</em></h1><p>嗨，小探险家！准备好今天的英语奇遇了吗？<br>一起收集知识的星星，发现更大的世界！</p><button class="primary" @click="start()">开始今日冒险　→</button></div><div class="landscape"><div class="sun"></div><div class="cloud c1"></div><div class="cloud c2"></div><div class="mountain m1"></div><div class="mountain m2"></div><div class="hill h1"></div><div class="hill h2"></div><span class="fox">🦊</span><span class="tree t1">🌳</span><span class="tree t2">🌲</span><span class="flower">🌼</span></div></section>
<div class="section-heading"><div><small>YOUR ADVENTURE</small><h2>今天去哪里探索？</h2></div><span class="muted">选择一片领地，开始学习</span></div>
<div class="worlds"><button class="world forest" @click="page='cards'"><span class="world-icon">🌿</span><small>01 · VOCABULARY</small><strong>单词森林</strong><span>翻转闪卡，认识新朋友</span><b>进入探索　→</b></button><button class="world workshop" @click="start()"><span class="world-icon">🧩</span><small>02 · PRACTICE</small><strong>奇趣练习场</strong><span>词义、拼写、短语与句式</span><b>开始挑战　→</b></button><button class="world castle" @click="start(true)"><span class="world-icon">🏰</span><small>03 · REVIEW</small><strong>记忆城堡</strong><span>重新挑战还没掌握的知识</span><b>巩固记忆　→</b></button></div>
<button class="studio-promo" @click="page='studio'"><span>✦ V1.1 NEW</span><strong>语言探索工坊</strong><small>短语 · 句式 · 情景对话</small><b>进入探索 →</b></button><div class="bottom-grid"><section class="panel"><small>LEARNING JOURNEY</small><h3>我的学习旅程</h3><p>{{course.unit}} <span class="muted">· {{course.edition}}</span></p><div class="bar"><span :style="{width:percent+'%'}"></span></div><div class="progress-foot"><span>{{mastered}} / {{course.questions.length}} 道题已掌握</span><strong>{{percent}}%</strong></div></section><section class="panel mascot-panel"><span>✨</span><div><small>A LITTLE REMINDER</small><h3>每天一点点，进步看得见！</h3><p>今天也要给自己一个大大的赞。</p></div></section></div></template>
<template v-else-if="page==='studio'"><LearningStudio /></template><template v-else-if="page==='cards'"><div class="section-heading"><div><small>VOCABULARY FOREST</small><h2>单词森林</h2></div><span class="muted">{{cardIndex+1}} / {{course.cards.length}}</span></div><section class="flashcard" @click="flipped=!flipped" tabindex="0" @keydown.enter="flipped=!flipped"><template v-if="!flipped"><span class="card-emoji">{{course.cards[cardIndex].emoji}}</span><h2>{{course.cards[cardIndex].word}}</h2><p>点击卡片翻转，查看中文释义</p></template><template v-else><span class="card-emoji">✦</span><h2>{{course.cards[cardIndex].meaning}}</h2><p>{{course.cards[cardIndex].example}}</p></template></section><div class="card-actions"><button class="secondary" @click="cardIndex=(cardIndex+course.cards.length-1)%course.cards.length;flipped=false">← 上一张</button><button class="secondary" @click="speak(course.cards[cardIndex].word)">🔊 听发音</button><button class="primary" @click="cardIndex=(cardIndex+1)%course.cards.length;flipped=false">下一张 →</button></div></template>
<template v-else><div class="section-heading"><div><small>{{review?'REVIEW CHALLENGE':'PRACTICE ADVENTURE'}}</small><h2>{{review?'错题回顾':'奇趣练习场'}}</h2></div><span class="muted">{{questions.length?index+1:0}} / {{questions.length}}</span></div><section v-if="!q" class="quiz panel"><div class="empty-icon">🎉</div><h2>目前没有需要复习的错题！</h2><p>继续保持，去探索更多知识吧。</p><button class="primary" @click="page='home'">返回首页</button></section><section v-else class="quiz panel"><div class="quiz-meta"><span class="tag">{{q.kind==='choice'?'词义选择':q.kind==='spell'?'单词拼写':q.kind==='phrase'?'短语练习':'句子拼图'}}</span><span class="muted">第 {{index+1}} 题</span></div><div class="bar"><span :style="{width:((index+1)/questions.length*100)+'%'}"></span></div><h2>{{q.prompt}}</h2><template v-if="q.kind==='choice'||q.kind==='phrase'"><div class="options"><button v-for="(opt,i) in q.options" :key="i" :class="{chosen:selected===opt}" :disabled="checked" @click="selected=opt"><span>{{String.fromCharCode(65+i)}}</span>{{opt}}</button></div></template><template v-else-if="q.kind==='spell'"><input v-model="selected" :disabled="checked" placeholder="在这里输入英语单词…" autocomplete="off" @keyup.enter="submit"/><button class="secondary listen" @click="speak(q.answer)">🔊 听一听正确读音</button></template><template v-else><div class="answer-slots"><button v-for="(id,i) in tokens" :key="i" :disabled="checked" @click="tokens.splice(i,1)">{{q.tokens![id]}}</button><span v-if="!tokens.length" class="muted">点击下面的词块组成句子…</span></div><div class="chunks"><button v-for="(word,i) in q.tokens" :key="i" :disabled="checked||tokens.includes(i)" @click="tokens.push(i)">{{word}}</button></div></template><div v-if="checked" class="feedback" :class="{wrong:!correct}"><strong>{{correct?'太棒了！回答正确 ✨':'再接再厉！这次还没答对'}}</strong><p v-if="!correct">正确答案：{{q.answer}} <span v-if="q.hint">· {{q.hint}}</span></p></div><div class="quiz-actions"><button class="secondary" @click="page='home'">返回首页</button><button v-if="!checked" class="primary" :disabled="!answer.trim()" @click="submit">提交答案 →</button><button v-else class="primary" @click="next">{{index===questions.length-1?'完成挑战':'下一题 →'}}</button></div></section></template>
<footer>LinguaLand · 语言奇遇岛　/　原创示范单元，非译林版教材原文复刻</footer></main></div>
</template>